	"this_banner_appears_at_the_top_of_your_website_or_app_to_grab_attention_instantly_and_showcase_offers_or_promotions._you_can_add_as_many_banners_as_you_like._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_3:2." => "يظهر هذا البانر أعلى موقعك أو تطبيقك لجذب الانتباه فورًا وعرض العروض الترويجية. يمكنك إضافة أي عدد من البانرات. عند الرفع، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن أبعاد الصورة بنسبة 3:2.",
	"Popup_banner" => "البانر المنبثق",
	"popup_banner_appears_when_user_visit_website._it’s_a_specific_single_type_banner._you_can_active_only_one_banner_at_a_time._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_1:1." => "يظهر البانر المنبثق عند زيارة المستخدم للموقع، وهو بانر فردي؛ إذ لا يمكن تفعيل أكثر من بانر واحد في الوقت نفسه. عند الرفع، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن أبعاد الصورة بنسبة 1:1.",
	"Footer_banner" => "بانر التذييل",
	"this_banner_appears_at_the_bottom_of_the_home_page_before_the_footer_section_to_grab_attention_when_any_on_browse_to_footer_section_and_showcase_offers_or_promotions._you_can_add_only_one_banner._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_4:1." => "يظهر هذا البانر أسفل الصفحة الرئيسية قبل قسم التذييل لجذب الانتباه عند التصفح إليه وعرض العروض الترويجية. يمكنك إضافة بانر واحد فقط. عند الرفع، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن أبعاد الصورة بنسبة 4:1.",
	"Main_section_banner" => "بانر القسم الرئيسي",
	"main_section_banner_appears_below_at_the_main_banner_of_your_website_grab_attention_instantly_and_showcase_offers_or_promotions._you_can_add_maximum_2_banners_at_a_time._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_2:1." => "يظهر بانر القسم الرئيسي أسفل البانر الرئيسي لموقعك لجذب الانتباه فورًا وعرض العروض الترويجية. يمكنك إضافة بانرين كحد أقصى في الوقت نفسه. عند الرفع، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن أبعاد الصورة بنسبة 2:1.",
	"this_banner_appears_at_the_header_nav_bar_section_to_showcase_short_&_effective_offers._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_4:1." => "يظهر هذا البانر في شريط التنقل بالترويسة لعرض عروض قصيرة ومؤثرة. عند الرفع، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن أبعاد الصورة بنسبة 4:1.",
	"this_banner_appears_at_the_right_side_of_the_intro_section_in_the_website._you_can_add_as_many_banners_as_you_like_but_only_show_one_banner_at_a_time_in_the_website._when_uploading,_ensure_the_file_size_is_under_2_mb_and_the_image_ratio_is_1:2." => "يظهر هذا البانر على الجانب الأيمن من قسم المقدمة في الموقع. يمكنك إضافة أي عدد من البانرات، لكن يُعرض بانر واحد فقط في الوقت نفسه. عند الرفع، تأكد من أن حجم الملف أقل من 2 ميجابايت وأن أبعاد الصورة بنسبة 1:2.",
